using DobleCommander;
using System.Reflection;

static class FeatureTests {
 static int passed;
 static void Assert(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);passed++;}
 static IEnumerable<Control> Children(Control c){yield return c;foreach(Control child in c.Controls)foreach(var nested in Children(child))yield return nested;}
 static void Pump(Task task){var deadline=DateTime.UtcNow.AddSeconds(45);while(!task.IsCompleted){if(DateTime.UtcNow>deadline)throw new Exception("Task timeout");Application.DoEvents();Thread.Sleep(1);}task.GetAwaiter().GetResult();}
 static T Pump<T>(Task<T> task){Pump((Task)task);return task.GetAwaiter().GetResult();}
 static void Until(Func<bool> predicate){var deadline=DateTime.UtcNow.AddSeconds(20);while(!predicate()){if(DateTime.UtcNow>deadline)throw new Exception("Progress timeout");Application.DoEvents();Thread.Sleep(1);}}
 static bool Rejected(Task task){try{Pump(task);return false;}catch(IOException){return true;}}
 static CopyBatch Batch(LiteWindow form)=>(CopyBatch)typeof(LiteWindow).GetField("batch",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(form)!;
 sealed class FakeEjector:IUnitEjector {
  internal readonly Dictionary<string,int> Map=new(StringComparer.OrdinalIgnoreCase);internal readonly HashSet<int> VetoDisks=[];internal readonly HashSet<string> UnsupportedRoots=new(StringComparer.OrdinalIgnoreCase);internal bool Supported=true,Veto;internal int Requests;
  public int? DiskForPath(string path)=>Map.GetValueOrDefault(path,0);
  public Task<EjectCandidate?> QueryAsync(string root)=>Task.FromResult(Supported&&!UnsupportedRoots.Contains(root)?new EjectCandidate(root,"fake-identity","fake-device",1,[Map.GetValueOrDefault(root,1)]):null);
  public Task EjectAsync(EjectCandidate candidate){Requests++;return Veto||candidate.Disks.Any(VetoDisks.Contains)?Task.FromException(new IOException("Windows veto")):Task.CompletedTask;}
 }
 [STAThread] static int Main(string[] args){
  Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());
  var root=Path.Combine(Path.GetTempPath(),"Rcopies-features-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
  try{
   string Dir(string name){var path=Path.Combine(root,name);Directory.CreateDirectory(path);return path;}
   StorageUnit? Unit(string path)=>path.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)?new(path,Path.GetFileName(path),DriveType.Removable,500_000_000_000,400_000_000_000,"NTFS"):null;
   var source=Dir("source");File.WriteAllText(Path.Combine(source,"file.txt"),"Rcopies test");var a=Path.Combine(root,"unit-a");var b=Path.Combine(root,"unit-b");
   var text=MemoryMeter.DisplayText(new(200*1024*1024,900*1024*1024,4L*1024*1024*1024,8L*1024*1024*1024,true));Assert(text.Contains("RAM usada")&&text.Contains("RAM libre")&&!text.Contains("900")&&!text.Contains("6 ")&&!text.Contains("privada",StringComparison.OrdinalIgnoreCase),"RAM display includes only used and free memory");
   Assert(Branding.AppIcon.Width>=32&&Branding.Logo.Width==1024&&Branding.Watermark.Width==1024,"professional Windows icon and original watermark are embedded independently");
   Assert(Pump(new WindowsUnitEjector().QueryAsync(Path.GetPathRoot(Environment.SystemDirectory)!))==null,"native ejection discovery refuses the Windows volume without requesting removal");
   Assert(!WindowsUnitEjector.CanAscendPast(@"USB\VID_1234&PID_5678\serial")&&WindowsUnitEjector.CanAscendPast(@"USB\VID_1234&PID_5678&MI_00\serial")&&WindowsUnitEjector.CanAscendPast(@"SCSI\Disk&Ven_example\serial"),"ejection discovery stops at the physical USB device instead of escalating to its hub");
   using(var free=new LiteWindow(false,Dir("free-logs"),Unit,()=>false)){
    free.ConfigureCopy(true,Conflict.Compare,false);free.SetSource(source);free.AddPaths([a]);Assert(!free.FullLicense,"application opens in free mode without activation");Pump(free.StartCopyAsync());Assert(File.Exists(Path.Combine(a,"file.txt")),"free copy writes to one destination");
    free.AddPaths([b]);Assert(Rejected(free.StartCopyAsync())&&!Directory.Exists(b),"free mode rejects two selected destinations before writes");free.SelectTarget(a,false);Pump(free.StartCopyAsync());Assert(File.Exists(Path.Combine(b,"file.txt")),"free mode allows sequential single-destination operations");
    var manifest=Pump(MirrorPlanner.ReadSourceAsync(source));var pa=Pump(MirrorPlanner.PreviewAsync(manifest,a));var pb=Pump(MirrorPlanner.PreviewAsync(manifest,b));Assert(Rejected(free.ExecuteMirrorAsync([pa,pb],false)),"free mode rejects multidestination mirror");
    File.WriteAllText(Path.Combine(b,"extra.txt"),"old");pb=Pump(MirrorPlanner.PreviewAsync(manifest,b));Pump(free.ExecuteMirrorAsync([pb],false));Assert(!File.Exists(Path.Combine(b,"extra.txt")),"free single-destination mirror completes");
    Assert(Children(free).All(c=>!c.Text.Contains("PHANTOM",StringComparison.OrdinalIgnoreCase)&&!c.Text.Contains("Creado by",StringComparison.OrdinalIgnoreCase))&&free.Text=="Rcopies","visible product has Rcopies name without old credits");
    var list=Children(free).OfType<ListView>().Single();Assert(list.ContextMenuStrip?.Items.Count==2,"destination context menu provides auxiliary and disconnect actions");
   }
   var plan=Plan.Create([source],true);var pool=new SourcePool(plan);pool.SetEnabled(a,false);Assert(!Pump(pool.PromoteAsync(a)),"disabled target cannot be promoted as a helper");pool.SetEnabled(a,true);Assert(Pump(pool.PromoteAsync(a)),"eligible completed target can be enabled as a helper");
   var lease=pool.Acquire(plan.Files[0],b);Assert(lease.HelperRoot==a&&pool.ActiveReaders(a)==1,"helper leases expose active readers");pool.SetEnabled(a,false);using(var next=pool.Acquire(plan.Files[0],b))Assert(next.HelperRoot==null&&pool.HelperCount==0,"disabled helper gets no new readers and primary takes over");lease.Dispose();Assert(pool.ActiveReaders(a)==0,"existing helper read drains safely after disabling");Assert(Pump(pool.PromoteAsync(a))==false,"manual opt-out prevents automatic re-promotion");
   var ejector=new FakeEjector();ejector.Map[a]=1;
   using(var form=new LiteWindow(false,Dir("eject-logs"),Unit,()=>true,ejector)){
    form.ConfigureCopy(true,Conflict.Compare,false);form.SetSource(source);form.AddPaths([a]);Pump(form.StartCopyAsync());var row=form.Targets.Single();var sources=Batch(form).Sources;using var held=sources.Acquire(Batch(form).Plan.Files[0],b);
    Assert(held.HelperRoot==a,"completed destination is actively leased before disconnect");var disconnect=form.RequestEjectAsync(row);Until(()=>!row.AllowAuxiliary);Assert(!disconnect.IsCompleted&&ejector.Requests==0,"disconnect waits for helper readers instead of forcing removal");held.Dispose();Pump(disconnect);Assert(ejector.Requests==1&&!form.Targets.Any(),"safe disconnect removes destination after readers drain");
   }
   var veto=new FakeEjector{Veto=true};veto.Map[a]=1;using(var form=new LiteWindow(false,Dir("veto-logs"),Unit,()=>true,veto)){form.ConfigureCopy(true,Conflict.Compare,false);form.SetSource(source);form.AddPaths([a]);Assert(Rejected(form.RequestEjectAsync(form.Targets.Single()))&&form.Targets.Any(),"Windows veto leaves the unit present");}
   var unsupported=new FakeEjector{Supported=false};using(var form=new LiteWindow(false,Dir("unsupported-logs"),Unit,()=>true,unsupported)){form.ConfigureCopy(true,Conflict.Compare,false);form.SetSource(source);form.AddPaths([a]);Assert(Rejected(form.RequestEjectAsync(form.Targets.Single()))&&unsupported.Requests==0,"unsupported storage cannot be disconnected");}
   var protectedDisk=new FakeEjector();protectedDisk.Map[a]=0;using(var form=new LiteWindow(false,Dir("protected-logs"),Unit,()=>true,protectedDisk)){form.ConfigureCopy(true,Conflict.Compare,false);form.SetSource(source);form.AddPaths([a]);Assert(Rejected(form.RequestEjectAsync(form.Targets.Single()))&&protectedDisk.Requests==0,"disk containing Windows or program paths cannot be disconnected");}
   var large=Dir("large-source");using(var file=File.Create(Path.Combine(large,"large.bin")))file.SetLength(128L*1024*1024);
   using(var ownCopy=new LiteWindow(false,Dir("own-copy-logs"),Unit,()=>true)){
    var target=Path.Combine(root,"own-copy-target");ownCopy.ConfigureCopy(true,Conflict.Compare,false);ownCopy.SetSource(large);ownCopy.AddPaths([target]);var task=ownCopy.StartCopyAsync();Until(()=>ownCopy.CopyPrepared&&ownCopy.Targets.Any(t=>t.Copy?.Status.Done>0)||task.IsCompleted);ownCopy.PauseSelected(true);var row=ownCopy.Targets.Single();var state=row.Copy!.Status.State;Pump(ownCopy.SetAuxiliaryAsync(row,false));Assert(row.Copy.Status.State==state&&!row.Copy.Token.IsCancellationRequested,"helper opt-out does not change its own destination copy state");ownCopy.ResumeSelected(true);Pump(task);Assert(row.Copy.Status.State=="Completado"&&!Batch(ownCopy).Sources.HelperRoots.Contains(target),"opted-out destination still completes its own copy without promotion");Assert(Pump(TestFiles.Hash(Path.Combine(target,"large.bin"),CancellationToken.None)).SequenceEqual(Pump(TestFiles.Hash(Path.Combine(large,"large.bin"),CancellationToken.None))),"own destination content remains intact after helper opt-out");
   }
   var multiple=new FakeEjector();multiple.Map[a]=1;multiple.Map[b]=2;using(var form=new LiteWindow(false,Dir("multi-eject-logs"),Unit,()=>true,multiple)){form.ConfigureCopy(true,Conflict.Compare,false);form.SetSource(source);form.AddPaths([a,b]);form.Show();Application.DoEvents();var list=Children(form).OfType<ListView>().Single();list.Items[0].Focused=true;var menu=list.ContextMenuStrip??throw new Exception("Missing context menu");menu.Show(list,new Point(70,35));Application.DoEvents();Assert((menu.Items[1].Text?.Contains("(2)")==true)&&menu.Items[1].Enabled,"context menu keeps the multiple selection and offers a batch action");menu.Close();var report=Pump(form.RequestEjectManyAsync(form.Targets.ToArray()));Assert(report.Length==2&&report.All(r=>r.Success)&&multiple.Requests==2&&!form.Targets.Any(),"multiple selected devices disconnect through one batch action");form.Close();}
   var shared=new FakeEjector();shared.Map[a]=shared.Map[b]=1;using(var form=new LiteWindow(false,Dir("shared-eject-logs"),Unit,()=>true,shared)){form.ConfigureCopy(true,Conflict.Compare,false);form.SetSource(source);form.AddPaths([a,b]);var report=Pump(form.RequestEjectManyAsync(form.Targets.ToArray()));Assert(report.All(r=>r.Success)&&shared.Requests==1&&!form.Targets.Any(),"partitions on the same physical device are ejected only once");}
   var partial=new FakeEjector();partial.Map[a]=1;partial.Map[b]=2;partial.VetoDisks.Add(2);using(var form=new LiteWindow(false,Dir("partial-eject-logs"),Unit,()=>true,partial)){form.ConfigureCopy(true,Conflict.Compare,false);form.SetSource(source);form.AddPaths([a,b]);var report=Pump(form.RequestEjectManyAsync(form.Targets.ToArray()));Assert(report.Count(r=>r.Success)==1&&report.Count(r=>!r.Success)==1&&form.Targets.Single().Path==b,"batch ejection preserves vetoed units and reports each result");}
   var mixed=new FakeEjector();mixed.Map[a]=1;mixed.Map[b]=2;mixed.UnsupportedRoots.Add(a);using(var form=new LiteWindow(false,Dir("mixed-eject-logs"),Unit,()=>true,mixed)){form.ConfigureCopy(true,Conflict.Compare,false);form.SetSource(source);form.AddPaths([a,b]);var report=Pump(form.RequestEjectManyAsync(form.Targets.ToArray()));Assert(report.Count(r=>r.Success)==1&&mixed.Requests==1&&form.Targets.Single().Path==a,"unsupported selected units do not prevent safe ejection of others");}
   var busyEjector=new FakeEjector();var active=Path.Combine(root,"active-unit");busyEjector.Map[a]=busyEjector.Map[active]=1;
   using(var form=new LiteWindow(false,Dir("busy-logs"),Unit,()=>false,busyEjector)){
    form.ConfigureCopy(true,Conflict.Compare,false);form.SetSource(large);form.AddPaths([a,active]);form.SelectTarget(a,false);var task=form.StartCopyAsync();Until(()=>form.CopyPrepared&&form.Targets.Any(t=>t.Copy?.Status.Done>0)||task.IsCompleted);form.PauseSelected(true);
    Assert(Rejected(form.RequestEjectAsync(form.Targets.Single(t=>t.Path==a)))&&busyEjector.Requests==0,"another active partition on the same device blocks disconnect");
    form.SelectTarget(a,true);form.SelectTarget(active,false);bool rejected=false;try{form.JoinSelectedTargets();}catch(IOException){rejected=true;}Assert(rejected,"free mode cannot bypass one-destination limit through late admission");Pump(form.CancelAsync(true));Pump(task);
   }
   if(args.Length==2&&args[0]=="--render"){using var form=new LiteWindow(false,Dir("preview-logs"),Unit,()=>false);form.ConfigureCopy(true,Conflict.Compare,false);form.SetSource(source);form.AddPaths([a]);form.Show();Application.DoEvents();Pump(form.StartCopyAsync());using var image=new Bitmap(form.Width,form.Height);form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(args[1],System.Drawing.Imaging.ImageFormat.Png);form.Close();}
   Console.WriteLine($"{passed} Rcopies feature assertions passed. All ejection requests were simulated; no physical device was disconnected.");return 0;
  }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{if(Directory.Exists(root))Directory.Delete(root,true);}
 }
}
